export const dynamic = "force-dynamic";

import { NextResponse } from "next/server";
import { z } from "zod";
import { requireUser } from "@/lib/auth";
import { prisma } from "@/lib/db";

// Add a LinkedIn post that wasn't generated by this tool. Stored as
// a Render row with format="external" so the existing /posts archive
// + community feed pick it up automatically — same eligibility rules
// (trackedAt + impressions > 0 surfaces it on Community / Top, and
// it counts toward the author's stats line on /members).
//
// Externals carry a title (filename) + post URL + the standard
// engagement metrics, but no rendered file or sourceHtml. The UI
// hides Remix / Open-file / file thumbnail for them.
const Body = z.object({
  title: z.string().trim().min(1).max(120),
  post_url: z.string().trim().url().nullable().optional(),
  impressions: z.coerce.number().int().min(0).max(2_000_000_000).nullable().optional(),
  reactions: z.coerce.number().int().min(0).max(2_000_000_000).nullable().optional(),
  comments: z.coerce.number().int().min(0).max(2_000_000_000).nullable().optional(),
  reposts: z.coerce.number().int().min(0).max(2_000_000_000).nullable().optional(),
});

export async function POST(req: Request) {
  let user;
  try {
    user = await requireUser();
  } catch (res) {
    return res as Response;
  }

  const parsed = Body.safeParse(await req.json().catch(() => ({})));
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 });
  }

  // Stamp trackedAt only if any engagement metric was supplied or a
  // post URL is present — otherwise the row is just a placeholder
  // and shouldn't show up on the community wall yet. The user can
  // always re-edit later via the standard PATCH /api/render/[id]
  // path; that endpoint will set trackedAt at that point.
  const hasMetric =
    (parsed.data.impressions ?? null) !== null ||
    (parsed.data.reactions ?? null) !== null ||
    (parsed.data.comments ?? null) !== null ||
    (parsed.data.reposts ?? null) !== null ||
    !!parsed.data.post_url;

  const created = await prisma.render.create({
    data: {
      userId: user.id,
      filename: parsed.data.title,
      format: "external",
      status: "complete",
      completedAt: new Date(),
      postUrl: parsed.data.post_url ?? null,
      impressions: parsed.data.impressions ?? null,
      reactions: parsed.data.reactions ?? null,
      comments: parsed.data.comments ?? null,
      reposts: parsed.data.reposts ?? null,
      trackedAt: hasMetric ? new Date() : null,
    },
    select: { id: true },
  });

  return NextResponse.json({ id: created.id });
}
